  visible: boolean;
  overlay?: { id?:number; kind: string; bounds: Rectangle; tabId?: string; context?: { tabId?: string; url?: string; /** A bookmark menu opened on a folder, a bookmark by id, the zone (root) or new:<parent> (G). */ node?: string; query?: string; index?: number; lockedTop?:number; toasts?: { id: number; text: string; action?: ToastAction; tone?:'error'|'info' }[]; expanded?: boolean; status?: { key: number; text: string; icon?: StatusIcon }; items?: PageMenuItem[]; input?: 'keyboard'; /** The Tor panel opened already asking "New Tor identity?" (menu row, Ctrl+Shift+U). */ intent?: 'identity' | 'report'; from?: { x: number; y: number }; trigger?: Rectangle; /** R3-42: a submenu opened from the Acira menu (it shows a way back), and the menu reopened from one (it slides in from the left). */ parent?: 'menu'; level?: 'back'; /** R4-61: the feature-rating card, carried on the transient (toast) layer over a website. */ rating?: { feature: RatingFeature; phase: 'ask' | 'thanks'; leaving: boolean } }; anchor?: Rectangle; origin?: { x: number; y: number }; contentHeight?: number; auxiliaryBounds?: Rectangle };
